import base64,hashlib,json,os,subprocess
from pathlib import Path
R=Path('/dataset/shaoshitong/search-r1-rl/bapo-fresh200-controller-initfix-20261006')
S='60f566b3ddabc88ce9de56ead5ad30a3d6795dd2'
assert R.resolve()==R and os.uname().nodename=='h100-5'
assert subprocess.check_output(['git','-C',str(R/'repo'),'rev-parse','HEAD'],text=True).strip()==S
receipt=json.loads((R/'scheduler-head/formal200-receipt.json').read_text());assert str(receipt['job_id'])=='3315' and receipt['source']==S
PAYLOAD=[['logs/first5-v4-portable.tar', '7d47e9259930b7dbec5e0a31dea19befc3f334815ffe477b2e55ad93bbdb7ff1', ''], ['logs/install-first5-v4-reviewed.py', '6ddfc1bb1b356d984770eeea27e3e4ae4ac13e44bc9b30f015d1e57e267f3cc3', ''], ['logs/reviews/3315-FIRST5-V4-NATIVE-FORMAT-PACKAGE-INDEPENDENT-CODE-REVIEW.json', '8fa99cb77515489b68af653a8a37b04a347f955fd0c8ce23912f03d9cdc25ae1', '']]
for name,h,b in PAYLOAD:
 p=R/name;assert R in p.parents and p.resolve()==p and not p.exists() and not p.is_symlink()
 assert hashlib.sha256(base64.b64decode(b,validate=True)).hexdigest()==h
for name,h,b in PAYLOAD:
 p=R/name;p.parent.mkdir(exist_ok=True)
 with p.open('xb')as f:f.write(base64.b64decode(b));f.flush();os.fsync(f.fileno())
 assert hashlib.sha256(p.read_bytes()).hexdigest()==h
env=dict(os.environ,PYTHONPATH=str(R/'repo'),PYTHONDONTWRITEBYTECODE='1',CUDA_VISIBLE_DEVICES='',HF_HUB_OFFLINE='1',OMP_NUM_THREADS='1',MKL_NUM_THREADS='1');env.pop('PYTHONOPTIMIZE',None)
a=[str(R/'env/bin/python'),'-B',str(R/PAYLOAD[1][0]),'--package',str(R/PAYLOAD[0][0]),'--source-commit',S,'--review',str(R/PAYLOAD[2][0]),'--expected-review-sha',PAYLOAD[2][1],'--execute-worker']
p=subprocess.run(a,cwd=str(R/'repo'),env=env)
print(json.dumps({'scope':'ACTUAL_LINUX33_CODE_TOOLS_ONLY_NOT_FIRST5','installer_exit_code':p.returncode}),flush=True)
raise SystemExit(p.returncode)
